CREATE OR REPLACE FUNCTION public.get_discover_queue(media_type text DEFAULT 'film',filters jsonb DEFAULT '{}',exclude_ids uuid[] DEFAULT '{}',seed text DEFAULT '',"limit" integer DEFAULT 8) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$
DECLARE uid uuid:=auth.uid(); result jsonb;
BEGIN
IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
WITH candidates AS MATERIALIZED (
SELECT i.* FROM items i JOIN profiles p ON p.id=uid WHERE i.media_type=get_discover_queue.media_type AND (NOT coalesce((filters->>'georgian_only')::boolean,false) OR i.is_georgian) AND NOT i.id=ANY(exclude_ids) AND NOT i.genres&&p.avoided_genres AND NOT EXISTS(SELECT 1 FROM swipes s WHERE s.user_id=uid AND s.item_id=i.id) AND NOT EXISTS(SELECT 1 FROM logs l WHERE l.user_id=uid AND l.item_id=i.id AND l.status='seen') AND NOT EXISTS(SELECT 1 FROM item_facets f JOIN user_taste_overrides o ON o.facet=f.facet AND o.value=f.value AND o.user_id=uid AND o.stance='avoid' WHERE f.item_id=i.id) AND (NOT filters?'facet' OR EXISTS(SELECT 1 FROM item_facets f WHERE f.item_id=i.id AND f.facet=filters->>'facet' AND f.value=filters->>'value')) AND (NOT filters?'tag' OR filters->>'tag'=ANY(i.genres||i.mood_tags||i.keywords||ARRAY['creator:'||i.creator])) ORDER BY CASE WHEN p.swipe_no=0 THEN coalesce(i.popularity,0) END DESC NULLS LAST,md5(i.id::text||seed) LIMIT 300
),evidence AS (
SELECT c.id,f.facet,f.value,f.confidence,ut.defining,coalesce(ut.importance,0.1) importance,
CASE WHEN o.stance='love' THEN 1 WHEN ut.stance='loves' THEN 1 WHEN ut.stance='leans_toward' THEN 0.5 WHEN ut.stance='leans_away' THEN -0.5 WHEN ut.stance='avoids' THEN -1 ELSE 0 END * f.confidence * CASE WHEN o.stance IS NOT NULL THEN 1 WHEN ut.confidence_level='strong' THEN 1 WHEN ut.confidence_level='established' THEN 0.8 ELSE 0.5 END * CASE WHEN ut.media_type IS DISTINCT FROM c.media_type THEN 0.5 ELSE 1 END contribution
FROM candidates c JOIN item_facets f ON f.item_id=c.id LEFT JOIN user_taste_overrides o ON o.user_id=uid AND o.facet=f.facet AND o.value=f.value
LEFT JOIN LATERAL (SELECT t.* FROM user_taste t WHERE t.user_id=uid AND t.facet=f.facet AND t.value=f.value AND (t.media_type=c.media_type OR f.facet IN ('tone','themes','pace','era','origin','complexity','ending') AND NOT EXISTS(SELECT 1 FROM user_taste own WHERE own.user_id=uid AND own.media_type=c.media_type AND own.facet=f.facet AND own.confidence_level IN ('established','strong'))) ORDER BY (t.media_type=c.media_type) DESC LIMIT 1) ut ON true
),groups AS (SELECT id,facet,avg(contribution)*max(importance) score FROM evidence GROUP BY id,facet),matched AS (SELECT id,array_agg(value ORDER BY contribution DESC) FILTER(WHERE contribution>0) matches,count(*) FILTER(WHERE defining AND contribution>0) defining_hits,bool_or(contribution=0 AND importance>=0.1) unknown FROM evidence GROUP BY id),scored AS (
SELECT c.*,coalesce((SELECT sum(score) FROM groups g WHERE g.id=c.id),0)+coalesce(t.weight,0)*0.02+coalesce((SELECT sum(least(0.2,greatest(-0.2,weight/25.0))) FROM tag_weights w WHERE w.user_id=uid AND w.tag=ANY(c.genres||c.mood_tags||c.keywords) AND NOT EXISTS(SELECT 1 FROM item_facets f WHERE f.item_id=c.id)),0)+(('x'||substr(md5(c.id::text||seed),1,6))::bit(24)::int)/16777215.0*0.05 score,m.matches,(m.defining_hits>0 AND (m.unknown OR m.defining_hits<(SELECT count(*) FROM user_taste u WHERE u.user_id=uid AND u.media_type=c.media_type AND u.defining))) probe FROM candidates c LEFT JOIN tag_weights t ON t.user_id=uid AND t.tag='creator:'||c.creator LEFT JOIN matched m ON m.id=c.id
),ranked AS (SELECT s.*,row_number() OVER(PARTITION BY is_georgian ORDER BY score DESC) group_no FROM scored s),ordered AS (SELECT r.*,CASE WHEN is_georgian THEN group_no*(CASE p.georgian_preference WHEN 'less' THEN 12 WHEN 'more' THEN 3 ELSE 6 END) ELSE group_no+floor((group_no-1)::numeric/(CASE p.georgian_preference WHEN 'less' THEN 11 WHEN 'more' THEN 2 ELSE 5 END)) END slot FROM ranked r JOIN profiles p ON p.id=uid),base AS (SELECT o.*,row_number() OVER(ORDER BY CASE WHEN coalesce((filters->>'georgian_only')::boolean,false) THEN group_no ELSE slot END,score DESC) position FROM ordered o),probe_pick AS (SELECT id FROM base WHERE probe AND position>=5 ORDER BY score DESC LIMIT 1),final AS (SELECT b.*,CASE WHEN b.id=(SELECT id FROM probe_pick) THEN 4.5 ELSE position::numeric END ordering FROM base b),picked AS (SELECT * FROM final ORDER BY ordering LIMIT greatest(1,least(8,get_discover_queue."limit")))
SELECT coalesce(jsonb_agg(jsonb_build_object('item',jsonb_build_object('id',id,'media_type',picked.media_type,'title_en',title_en,'title_ka',title_ka,'creator',creator,'year',year,'genres',genres,'mood_tags',mood_tags,'keywords',keywords,'runtime_minutes',runtime_minutes,'page_count',page_count,'image_source',image_source,'image_ref',image_ref,'is_georgian',is_georgian,'tmdb_id',tmdb_id),'reason',CASE WHEN id=(SELECT id FROM probe_pick) THEN 'Exploring your taste: '||coalesce(replace(array_to_string(matches[1:2],', '),'_',' '),'familiar traits')||' in a different combination.' WHEN cardinality(matches)>0 THEN initcap(replace(array_to_string(matches[1:3],', '),'_',' '))||': traits you keep coming back to.' ELSE 'A varied starter pick.' END,'matched',coalesce(matches,'{}'),'score',score,'exploratory',id=(SELECT id FROM probe_pick)) ORDER BY ordering),'[]') INTO result FROM picked;
RETURN result;END $$;
REVOKE ALL ON FUNCTION public.get_discover_queue(text,jsonb,uuid[],text,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.get_discover_queue(text,jsonb,uuid[],text,integer) TO authenticated;